import { Component, Prop, Vue } from 'vue-property-decorator';
import SvgIcon from '../svg-icon/index.vue';

@Component({
    name: 'MenuArrow',
    components: {
        SvgIcon
    }
})
export default class MenuArrow extends Vue {
    @Prop({
        type: String,
        required: false,
        default: 'right'
    })
    public direction: string;

    @Prop({
        type: Boolean,
        required: false,
        default: false
    })
    public isLoading: boolean;

    public get classes() {
        return {
            [`${this.direction}`]: true,
            ['loading']: this.isLoading
        };
    }
}
